visual.raw:
const labelMap = {
  pending: '待审批',
  approved: '已批准',
  rejected: '已驳回',
  withdrawn: '已撤回'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.status] || r.status, value: Number(r.leaveCount) || 0 };
});
return {
  tooltip: { trigger: 'item' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', radius: '62%', name: '请假状态分布', data: data, label: { formatter: '{b}: {c}' } }
  ]
};
